import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new THREE.Group();
  group.name = 'brand-mark-wall';

  const colors = config.intent?.visualSpec?.colors ?? config.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#1a1a22' }, { at: 1, hex: '#121218' }],
  };

  const gradientTop = colors.gradientStops?.[0]?.hex ?? '#1a1a22';
  const gradientBottom = colors.gradientStops?.[1]?.hex ?? '#121218';
  const paper = colors.paper ?? '#e8ecf2';

  const disposables = [];
  const timelines = [];

  // ---------- STAGE BACKDROP ----------
  const backdropGeo = new THREE.PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = mix(color(gradientBottom), color(gradientTop), uv().y);
  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------- RAKE KEY LIGHT (node-local, cap <=1.5) ----------
  const elevRad = THREE.MathUtils.degToRad(35);
  const rakeLight = new THREE.DirectionalLight(0xffffff, 1.3);
  rakeLight.position.set(Math.cos(elevRad) * 4, Math.sin(elevRad) * 4, 3.5);
  group.add(rakeLight);
  group.add(rakeLight.target);

  // ---------- TEXT CONTENT ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const kickerItem = items.find((i) => i.role === 'kicker');
  const brandItems = items.filter((i) => i.role === 'brand-mark');

  const typography = config.intent?.visualSpec?.typography ?? {};
  const kickerType = typography.kicker ?? { fontSize: 9, letterSpacing: 0.12 };
  const brandType = typography['brand-mark'] ?? { fontSize: 13, letterSpacing: 0.08 };

  // ---------- GRID LAYOUT ----------
  const TILE_W = 1.0;
  const TILE_H = 0.62;
  const GAP = 0.25;
  const cols = [-(TILE_W + GAP), 0, (TILE_W + GAP)];
  const rows = [
    (TILE_H + GAP) / 2, // top
    -(TILE_H + GAP) / 2, // bottom
  ];

  const gridTop = rows[0] + TILE_H / 2;
  const kickerY = gridTop + 0.3;

  // Kicker text
  let kickerText = null;
  if (kickerItem) {
    kickerText = ctx.fontAtlas.createText(kickerItem.text ?? 'AS FEATURED IN', {
      fontSize: kickerType.fontSize ?? 9,
      color: paper,
      align: 'center',
      letterSpacingPx: (kickerType.fontSize ?? 9) * (kickerType.letterSpacing ?? 0.12),
    });
    kickerText.position.set(0, kickerY, -1.4);
    group.add(kickerText);
  }

  // ---------- TILES ----------
  const tileDepth = 0.05;
  const tiles = [];

  const positions = [
    [cols[0], rows[0]], [cols[1], rows[0]], [cols[2], rows[0]], // top row L->R
    [cols[0], rows[1]], [cols[1], rows[1]], [cols[2], rows[1]], // bottom row L->R
  ];

  for (let i = 0; i < 6; i++) {
    const [x, y] = positions[i];
    const item = brandItems[i];

    const geo = new THREE.BoxGeometry(TILE_W, TILE_H, tileDepth, 4, 4, 1);
    const mat = new MeshPhysicalNodeMaterial();
    mat.colorNode = mix(color(gradientTop), color(gradientBottom), uv().y);
    mat.roughness = 0.55;
    mat.metalness = 0.5;
    mat.clearcoat = 0.2;
    mat.clearcoatRoughness = 0.3;
    mat.anisotropy = 0.6;
    mat.anisotropyRotation = 0; // aligned to x
    mat.transparent = true;
    mat.opacity = 1;

    const mesh = new THREE.Mesh(geo, mat);
    const baseZ = 0;
    mesh.position.set(x, y - 0.2, baseZ); // start offset for fade-up (+0.2 -> 0)

    group.add(mesh);
    disposables.push(geo, mat);

    // wordmark
    let textObj = null;
    if (item) {
      textObj = ctx.fontAtlas.createText(item.text ?? '', {
        fontSize: brandType.fontSize ?? 13,
        color: paper,
        align: 'center',
        letterSpacingPx: (brandType.fontSize ?? 13) * (brandType.letterSpacing ?? 0.08),
      });
      textObj.position.set(x, y - 0.2, baseZ + tileDepth / 2 + 0.01);
      group.add(textObj);
    }

    tiles.push({ mesh, textObj, baseX: x, baseY: y, baseZ });
  }

  // ---------- MOUNT ANIMATION: stagger-cards (fade-up, top row first) ----------
  const mountTl = gsap.timeline();
  tiles.forEach((tile, idx) => {
    mountTl.to(
      tile.mesh.position,
      { y: tile.baseY, duration: 0.5, ease: 'power2.out' },
      idx * 0.08
    );
    if (tile.textObj) {
      mountTl.to(
        tile.textObj.position,
        { y: tile.baseY, duration: 0.5, ease: 'power2.out' },
        idx * 0.08
      );
    }
  });
  timelines.push(mountTl);

  // ---------- HOVER BEHAVIOR ----------
  function findTile(evt) {
    const obj = evt?.object ?? evt;
    if (!obj) return null;
    return tiles.find((t) => t.mesh === obj || (t.textObj && (t.textObj === obj || t.textObj.children.includes(obj))));
  }

  function hoverIn(evt) {
    const tile = findTile(evt);
    if (!tile) return;
    const tl = gsap.timeline();
    tl.to(tile.mesh.position, { z: tile.baseZ + 0.05, duration: 0.16, ease: 'power2.out' }, 0);
    timelines.push(tl);
  }

  function hoverOut(evt) {
    const tile = findTile(evt);
    if (!tile) return;
    const tl = gsap.timeline();
    tl.to(tile.mesh.position, { z: tile.baseZ, duration: 0.16, ease: 'power2.out' }, 0);
    timelines.push(tl);
  }

  function handleClick(evt) {
    const tile = findTile(evt);
    if (!tile) return;
    const tl = gsap.timeline();
    tl.to(tile.mesh.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'power2.out' })
      .to(tile.mesh.scale, { x: 1, y: 1, z: 1, duration: 0.18, ease: 'back.out(2)' });
    timelines.push(tl);
  }

  group.userData.handlers = {
    onPointerEnter: hoverIn,
    onPointerOver: hoverIn,
    onPointerLeave: hoverOut,
    onPointerOut: hoverOut,
    onClick: handleClick,
  };

  // ---------- CLEANUP ----------
  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    timelines.length = 0;

    disposables.forEach((res) => {
      if (res && typeof res.dispose === 'function') res.dispose();
    });

    if (kickerText) {
      kickerText.traverse((child) => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (child.material.map) child.material.map.dispose();
          child.material.dispose();
        }
      });
    }

    tiles.forEach((tile) => {
      if (tile.textObj) {
        tile.textObj.traverse((child) => {
          if (child.geometry) child.geometry.dispose();
          if (child.material) {
            if (child.material.map) child.material.map.dispose();
            child.material.dispose();
          }
        });
      }
    });

    rakeLight.dispose?.();
  };

  return group;
}
